	else
	{
		vec = GetAvgUnitVector(
			PointD(-norms[k].y, norms[k].x),
			PointD(norms[j].y, -norms[j].x));
	}

	// now offset the original vertex delta units along unit vector
	PointD ptQ = PointD(path[j]);
	ptQ = TranslatePoint(ptQ, abs_delta * vec.x, abs_delta * vec.y);
	// get perpendicular vertices
	PointD pt1 = TranslatePoint(ptQ, group_delta_ * vec.y, group_delta_ * -vec.x);
	PointD pt2 = TranslatePoint(ptQ, group_delta_ * -vec.y, group_delta_ * vec.x);
	// get 2 vertices along one edge offset
	PointD pt3 = GetPerpendicD(path[k], norms[k], group_delta_);
	if (j == k)
	{
		PointD pt4 = PointD(pt3.x + vec.x * group_delta_, pt3.y + vec.y * group_delta_);
		PointD pt = IntersectPoint(pt1, pt2, pt3, pt4);
#ifdef USINGZ
		pt.z = ptQ.z;
#endif
		//get the second intersect point through reflecion
		group.path.push_back(Point64(ReflectPoint(pt, ptQ)));
		group.path.push_back(Point64(pt));
	}
	else
	{
		PointD pt4 = GetPerpendicD(path[j], norms[k], group_delta_);
		PointD pt = IntersectPoint(pt1, pt2, pt3, pt4);
#ifdef USINGZ
		pt.z = ptQ.z;
#endif
		group.path.push_back(Point64(pt));
		//get the second intersect point through reflecion
		group.path.push_back(Point64(ReflectPoint(pt, ptQ)));
	}
}

void ClipperOffset::DoMiter(PathGroup& group, const Path64& path, size_t j, size_t k, double cos_a)
{
	double q = group_delta_ / (cos_a + 1);
#ifdef USINGZ
	group.path.push_back(Point64(
		path[j].x + (norms[k].x + norms[j].x) * q,
		path[j].y + (norms[k].y + norms[j].y) * q,
		path[j].z));
#else
	group.path.push_back(Point64(
		path[j].x + (norms[k].x + norms[j].x) * q,
		path[j].y + (norms[k].y + norms[j].y) * q));
#endif
}

void ClipperOffset::DoRound(PathGroup& group, const Path64& path, size_t j, size_t k, double angle)
{
	if (deltaCallback64_) {
		// when deltaCallback64_ is assigned, group_delta_ won't be constant, 
		// so we'll need to do the following calculations for every arc.
		group_delta_ = deltaCallback64_(path, norms, j, k, group.end_type);
		abs_delta = fabs(group_delta_);
		arcTol = (arcTolerance_ > floating_point_tolerance ? arcTolerance_ : log10(2 + abs_delta) * default_arc_tolerance);
		stepsPer360 = pi / acos(1 - arcTol / abs_delta);
		step_sin = sin(2 * pi / stepsPer360);
		step_cos = cos(2 * pi / stepsPer360);
		if (group_delta_ < 0.0) step_sin = -step_sin;
		steps_per_rad = stepsPer360 / (2 * pi);
	}

	Point64 pt = path[j];
	PointD offsetVec = PointD(norms[k].x * group_delta_, norms[k].y * group_delta_);

	if (j == k) offsetVec.Negate();
#ifdef USINGZ
	group.path.push_back(Point64(pt.x + offsetVec.x, pt.y + offsetVec.y, pt.z));
#else
	group.path.push_back(Point64(pt.x + offsetVec.x, pt.y + offsetVec.y));
#endif
	int steps = static_cast<int>(std::ceil(steps_per_rad * std::abs(angle))); // #448, #456
	for (int i = 1; i < steps; ++i) // ie 1 less than steps
	{
		offsetVec = PointD(offsetVec.x * step_cos - step_sin * offsetVec.y,
			offsetVec.x * step_sin + offsetVec.y * step_cos);
#ifdef USINGZ
		group.path.push_back(Point64(pt.x + offsetVec.x, pt.y + offsetVec.y, pt.z));
#else
		group.path.push_back(Point64(pt.x + offsetVec.x, pt.y + offsetVec.y));
#endif
	}
	group.path.push_back(GetPerpendic(pt, norms[j], group_delta_));
}

void ClipperOffset::OffsetPoint(PathGroup& group, const Path64& path, size_t j, size_t& k)
{
	// Let A = change in angle where edges join
	// A == 0: ie no change in angle (flat join)
	// A == PI: eg 'spike'
	// sin(A) < 0: right turning
	// cos(A) < 0: change in angle is more than 90 degree

	if (path[j] == path[k]) { k = j; return; }

	double sin_a = CrossProduct(norms[j], norms[k]);
	double cos_a = DotProduct(norms[j], norms[k]);
	if (sin_a > 1.0) sin_a = 1.0;
	else if (sin_a < -1.0) sin_a = -1.0;

	if (deltaCallback64_) group_delta_ = deltaCallback64_(path, norms, j, k, group.end_type);
	if (cos_a > -0.99 && (sin_a * group_delta_ < 0)) // test for concavity first (#593)
	{
		// is concave
		group.path.push_back(GetPerpendic(path[j], norms[k], group_delta_));
		// this extra point is the only (simple) way to ensure that
		// path reversals are fully cleaned with the trailing clipper
		group.path.push_back(path[j]); // (#405)
		group.path.push_back(GetPerpendic(path[j], norms[j], group_delta_));
	}
	else if (cos_a > 0.999 && miter_limit_ > 1) // almost straight - less than 2.5 degree (#424) 
	{
		DoMiter(group, path, j, k, cos_a);
	}
	else if (group.join_type == JoinType::Miter)
	{
		// miter unless the angle is sufficiently acute to exceed ML
		if (cos_a > tempLim_ - 1) DoMiter(group, path, j, k, cos_a);
		else DoSquare(group, path, j, k);
	}
	else if (group.join_type == JoinType::Round)
		DoRound(group, path, j, k, std::atan2(sin_a, cos_a));
	// else if (group.join_type == JoinType::Bevel) 
	// ie cos_a == 0, which will always occur since 
	// sin(A) == 0 and cos(A) == 1 have already been
	// dealt with above.
	else DoSquare(group, path, j, k);

	k = j;
}

void ClipperOffset::OffsetPolygon(PathGroup& group, const Path64& path)
{
	group.path.clear();
	for (Path64::size_type i = 0, j = path.size() -1; i < path.size(); j = i, ++i)
		OffsetPoint(group, path, i, j);
	group.paths_out.push_back(group.path);
}

void ClipperOffset::OffsetOpenJoined(PathGroup& group, const Path64& path)
{
	OffsetPolygon(group, path);
	Path64 reverse_path(path);
	std::reverse(reverse_path.begin(), reverse_path.end());

	//rebuild normals // BuildNormals(reverse_path);
	std::reverse(norms.begin(), norms.end());
	norms.push_back(norms[0]);
	norms.erase(norms.begin());
	NegatePath(group.path);
	group.paths_out.push_back(group.path);
}

void ClipperOffset::OffsetOpenPath(PathGroup& group, const Path64& path)
{
	// do the line start cap
	if (deltaCallback64_) group_delta_ = deltaCallback64_(path, norms, 0, 0, group.end_type);

	switch (group.end_type)
	{
	case EndType::Butt:
#ifdef USINGZ
		group.path.push_back(Point64(
			path[0].x - norms[0].x * group_delta_,
			path[0].y - norms[0].y * group_delta_,
			path[0].z));
		group.path.push_back(GetPerpendic(path[0], norms[0], group_delta_));
#else
		group.path.push_back(Point64(
			path[0].x - norms[0].x * group_delta_,
			path[0].y - norms[0].y * group_delta_));
		group.path.push_back(GetPerpendic(path[0], norms[0], group_delta_));
#endif
		break;
	case EndType::Round:
		DoRound(group, path, 0, 0, PI);
		break;
	default:
		DoSquare(group, path, 0, 0);
		break;
	}

	size_t highI = path.size() - 1;
	// offset the left side going forward
	for (Path64::size_type i = 1, k = 0; i < highI; ++i)
		OffsetPoint(group, path, i, k);

	// offset the left side going back
	for (Path64::size_type i = highI; i > 0; --i)
		norms[i] = PointD(-norms[i - 1].x, -norms[i - 1].y);
	norms[0] = norms[highI];

	// do the line end cap
	switch (group.end_type)
	{
	case EndType::Butt:
#ifdef USINGZ
		group.path.push_back(Point64(
			path[highI].x - norms[highI].x * group_delta_,
			path[highI].y - norms[highI].y * group_delta_,
			path[highI].z));
		group.path.push_back(GetPerpendic(path[highI], norms[highI], group_delta_));
#else
		group.path.push_back(Point64(
			path[highI].x - norms[highI].x * group_delta_,
			path[highI].y - norms[highI].y * group_delta_));
		group.path.push_back(GetPerpendic(path[highI], norms[highI], group_delta_));
#endif
		break;
	case EndType::Round:
		DoRound(group, path, highI, highI, PI);
		break;
	default:
		DoSquare(group, path, highI, highI);
		break;
	}

	// offset the left side going back
	for (Path64::size_type i = highI, k = highI; i > 0; --i)
		OffsetPoint(group, path, i, k);

	group.paths_out.push_back(group.path);
}

