```cpp
template <typename T>
inline double Area(const Path<T>& path)
{
	size_t cnt = path.size();
	if (cnt < 3) return 0.0;
	double a = 0.0;
	typename Path<T>::const_iterator it1, it2 = path.cend() -1, stop = path.cend();
	if (!(cnt & 1)) stop = path.cend() -1;
	for (it1 = path.cbegin(); it1 != stop;)
	{
		a += static_cast<double>(it2->y + it1->y) * (it2->x - it1->x);
		it2 = it1 +1;
		a += static_cast<double>(it1->y + it2->y) * (it1->x - it2->x);
		it1 += 2;
	}
	if (cnt & 1)
	{
		a += static_cast<double>(it2->y + it1->y) * (it2->x - it1->x);
		it2 = path.cbegin();
		a += static_cast<double>(it1->y + it2->y) * (it1->x - it2->x);
	}
	return a * 0.5;
}
```

