Path64 StripDuplicates(const Path64& path, bool is_closed_path)
{
	if (path.size() == 0) return Path64();
	Path64 result;
	result.reserve(path.size());
	Path64::const_iterator iter;
	for (iter = path.cbegin(); iter != path.cend(); ++iter)
	{
		if (result.size() == 0 || !(*iter == result.back()))
			result.push_back(*iter);
	}
	if (is_closed_path)
		while (result.size() > 1 && result.back() == result.front()) result.pop_back();
	return result;
}
