```rust
fn do_group_offset(&mut self, gi: usize, delta: f64) {
    let mut delta = delta;
    let et = self.groups[gi].et;
    if et != EndType::Polygon { delta = delta.abs() * 0.5; }
    if delta == 0.0 { return; }
    self.group_delta = delta;
    self.abs_delta = delta.abs();

    self.arc_tol = if self.arc_tolerance > FLOATING_POINT_TOLERANCE {
        self.arc_tolerance
    } else {
        (2.0 + self.abs_delta).log10() * DEFAULT_ARC_TOLERANCE
    };
    let mut steps_per_360 = PI / (1.0 - self.arc_tol / self.abs_delta).acos();
    if steps_per_360 > self.abs_delta * PI { steps_per_360 = self.abs_delta * PI; }
    if self.groups[gi].jt == JoinType::Round {
        self.step_sin = (2.0 * PI / steps_per_360).sin();
        self.step_cos = (2.0 * PI / steps_per_360).cos();
        if self.group_delta < 0.0 { self.step_sin = -self.step_sin; }
    }
    self.steps_per_rad = steps_per_360 / (2.0 * PI);

