fn offset_point(&mut self, gi: usize, path: &Path64, j: usize, k: &mut usize) {
    if path[j] == path[*k] { *k = j; return; }
    let mut sin_a = cross(self.norms[j], self.norms[*k]);
    let cos_a = dot(self.norms[j], self.norms[*k]);
    if sin_a > 1.0 { sin_a = 1.0; } else if sin_a < -1.0 { sin_a = -1.0; }

    if cos_a > -0.999 && sin_a * self.group_delta < 0.0 {
        // concave
        push get_perpendic(path[j], norms[*k], group_delta);
        push path[j];
        push get_perpendic(path[j], norms[j], group_delta);
    } else if cos_a > 0.999 && self.miter_limit > 1.0 {
        self.do_miter(gi, path, j, *k, cos_a);
    } else if jt == Miter {
        if cos_a > self.temp_lim - 1.0 { do_miter } else { do_square }
    } else if jt == Round {
        self.do_round(gi, path, j, *k, sin_a.atan2(cos_a));
    } else if jt == Bevel {
        self.do_bevel(gi, path, j, *k);
    } else {
        self.do_square(gi, path, j, *k);
    }
    *k = j;
}
