fn strip_duplicates(path: &Path64, is_closed: bool) -> Path64 {
    let mut result: Path64 = Vec::with_capacity(path.len());
    for p in path {
        if result.last().map_or(true, |l| l.x != p.x || l.y != p.y) {
            result.push(*p);
        }
    }
    if is_closed {
        while result.len() > 1 {
            let (f, l) = (result[0], result[result.len()-1]);
            if f.x == l.x && f.y == l.y { result.pop(); } else { break; }
        }
    }
    result
}
