//! Pure-Rust re-implementation of Clipper2's `ClipperOffset` (polygon
//! offsetting / `InflatePaths`) for integer paths (`Paths64`).
//!
//! Reconstructed from the Clipper2 C++ algorithm (`clipper.offset.cpp`),
//! mirroring its floating-point math exactly:
//!   * unit normals via `hypot`
//!   * default arc tolerance = `log10(2 + |delta|) * 0.25`
//!   * `stepsPer360 = pi / acos(1 - arcTol / |delta|)`, clamped to
//!     `|delta| * pi`, and `steps_per_rad = stepsPer360 / (2*pi)`
//!   * round arcs generated by repeated sin/cos rotation steps
//!   * miter limit via `tempLim = 2 / miter_limit^2` comparisons on `cos(a)`
//!   * offset points rounded with `std::nearbyint` semantics
//!     (round-half-to-even) when converting back to integer coordinates
//!   * the raw offset result is cleaned by a union with FillRule::Positive

use crate::clipper::{area, union, FillRule, Path64, Paths64, Point64};

const DEFAULT_ARC_TOLERANCE: f64 = 0.25;
const FLOATING_POINT_TOLERANCE: f64 = 1e-12;
const PI: f64 = std::f64::consts::PI;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum JoinType {
    Round,
    Miter,
    Square,
    Bevel,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum EndType {
    Polygon,
    Joined,
    Butt,
    Round,
    Square,
}

/// Equivalent of Clipper2's `InflatePaths(paths, delta, jt, et)` with the
/// default miter limit (2.0) and default arc tolerance (0.0).
pub fn inflate_paths(paths: &Paths64, delta: f64, jt: JoinType, et: EndType) -> Paths64 {
    let mut co = ClipperOffset::new(2.0, 0.0);
    co.add_paths(paths, jt, et);
    co.execute(delta)
}

// ---------------------------------------------------------------------------
// std::nearbyint (default rounding mode = round-half-to-even) replacement.
// rustc 1.75 lacks f64::round_ties_even, so implement it manually.
// ---------------------------------------------------------------------------
#[inline]
fn round_half_even(x: f64) -> f64 {
    let floor = x.floor();
    let diff = x - floor;
    if diff < 0.5 {
        floor
    } else if diff > 0.5 {
        floor + 1.0
    } else if floor % 2.0 == 0.0 {
        floor
    } else {
        floor + 1.0
    }
}

#[inline]
fn to_point64(x: f64, y: f64) -> Point64 {
    Point64::new(round_half_even(x) as i64, round_half_even(y) as i64)
}

#[inline]
fn pt_eq(a: &Point64, b: &Point64) -> bool {
    a.x == b.x && a.y == b.y
}

// ---------------------------------------------------------------------------
// PointD and vector helpers (mirroring clipper.offset.cpp)
// ---------------------------------------------------------------------------
#[derive(Clone, Copy, Default)]
struct PtD {
    x: f64,
    y: f64,
}

impl PtD {
    #[inline]
    fn new(x: f64, y: f64) -> PtD {
        PtD { x, y }
    }
}

#[inline]
fn get_unit_normal(p1: &Point64, p2: &Point64) -> PtD {
    let dx = (p2.x - p1.x) as f64;
    let dy = (p2.y - p1.y) as f64;
    if dx == 0.0 && dy == 0.0 {
        return PtD::default();
    }
    let f = 1.0 / dx.hypot(dy);
    let dx = dx * f;
    let dy = dy * f;
    PtD::new(dy, -dx)
}

#[inline]
fn almost_zero(value: f64) -> bool {
    value.abs() < 0.001
}

#[inline]
fn hypot2(x: f64, y: f64) -> f64 {
    // faster than the more obvious std::hypot (matches Clipper2's Hypot)
    (x * x + y * y).sqrt()
}

#[inline]
fn normalize_vector(vec: PtD) -> PtD {
    let h = hypot2(vec.x, vec.y);
    if almost_zero(h) {
        return PtD::new(0.0, 0.0);
    }
    let inverse_hypot = 1.0 / h;
    PtD::new(vec.x * inverse_hypot, vec.y * inverse_hypot)
}

#[inline]
fn get_avg_unit_vector(vec1: PtD, vec2: PtD) -> PtD {
    normalize_vector(PtD::new(vec1.x + vec2.x, vec1.y + vec2.y))
}

#[inline]
fn is_closed_path(et: EndType) -> bool {
    et == EndType::Polygon || et == EndType::Joined
}

#[inline]
fn get_perpendic(pt: &Point64, norm: &PtD, delta: f64) -> Point64 {
    to_point64(pt.x as f64 + norm.x * delta, pt.y as f64 + norm.y * delta)
}

#[inline]
fn get_perpendic_d(pt: &Point64, norm: &PtD, delta: f64) -> PtD {
    PtD::new(pt.x as f64 + norm.x * delta, pt.y as f64 + norm.y * delta)
}

#[inline]
fn translate_point(pt: PtD, dx: f64, dy: f64) -> PtD {
    PtD::new(pt.x + dx, pt.y + dy)
}

#[inline]
fn reflect_point(pt: PtD, pivot: PtD) -> PtD {
    PtD::new(pivot.x + (pivot.x - pt.x), pivot.y + (pivot.y - pt.y))
}

#[inline]
fn cross_product(a: PtD, b: PtD) -> f64 {
    a.x * b.y - a.y * b.x
}

#[inline]
fn dot_product(a: PtD, b: PtD) -> f64 {
    a.x * b.x + a.y * b.y
}

fn intersect_point(pt1a: PtD, pt1b: PtD, pt2a: PtD, pt2b: PtD) -> PtD {
    if pt1a.x == pt1b.x {
        // vertical
        if pt2a.x == pt2b.x {
            return PtD::new(0.0, 0.0);
        }
        let m2 = (pt2b.y - pt2a.y) / (pt2b.x - pt2a.x);
        let b2 = pt2a.y - m2 * pt2a.x;
        PtD::new(pt1a.x, m2 * pt1a.x + b2)
    } else if pt2a.x == pt2b.x {
        // vertical
        let m1 = (pt1b.y - pt1a.y) / (pt1b.x - pt1a.x);
        let b1 = pt1a.y - m1 * pt1a.x;
        PtD::new(pt2a.x, m1 * pt2a.x + b1)
    } else {
        let m1 = (pt1b.y - pt1a.y) / (pt1b.x - pt1a.x);
        let b1 = pt1a.y - m1 * pt1a.x;
        let m2 = (pt2b.y - pt2a.y) / (pt2b.x - pt2a.x);
        let b2 = pt2a.y - m2 * pt2a.x;
        if m1 == m2 {
            return PtD::new(0.0, 0.0);
        }
        let x = (b2 - b1) / (m1 - m2);
        PtD::new(x, m1 * x + b1)
    }
}

fn strip_duplicates(path: &Path64, is_closed_path: bool) -> Path64 {
    if path.is_empty() {
        return Path64::new();
    }
    let mut result: Path64 = Vec::with_capacity(path.len());
    for p in path.iter() {
        match result.last() {
            Some(last) if pt_eq(last, p) => {}
            _ => result.push(*p),
        }
    }
    if is_closed_path {
        while result.len() > 1 && pt_eq(&result[result.len() - 1], &result[0]) {
            result.pop();
        }
    }
    result
}

/// Equivalent of Clipper2's GetBoundsAndLowestPolyIdx (only the lowest-polygon
/// index is needed here). "Lowest" = largest y, ties broken by smallest x.
fn get_lowest_poly_idx(paths: &Paths64) -> Option<usize> {
    let mut idx: isize = -1;
    let mut bottom: i64 = i64::MIN;
    let mut lpx: i64 = i64::MAX;
    for (i, path) in paths.iter().enumerate() {
        for p in path.iter() {
            if p.y >= bottom && (p.y > bottom || p.x < lpx) {
                idx = i as isize;
                lpx = p.x;
                bottom = p.y;
            }
        }
    }
    if idx < 0 {
        None
    } else {
        Some(idx as usize)
    }
}

// ---------------------------------------------------------------------------
// ClipperOffset
// ---------------------------------------------------------------------------
struct PathGroup {
    paths_in: Paths64,
    join_type: JoinType,
    end_type: EndType,
    path: Path64, // working buffer
    paths_out: Paths64,
    is_reversed: bool,
}

struct ClipperOffset {
    miter_limit: f64,
    arc_tolerance: f64,
    groups: Vec<PathGroup>,
    // per-execute / per-group working state
    group_delta: f64,
    abs_delta: f64,
    temp_lim: f64,
    steps_per_rad: f64,
    step_sin: f64,
    step_cos: f64,
    norms: Vec<PtD>,
}

impl ClipperOffset {
    fn new(miter_limit: f64, arc_tolerance: f64) -> ClipperOffset {
        ClipperOffset {
            miter_limit,
            arc_tolerance,
            groups: Vec::new(),
            group_delta: 0.0,
            abs_delta: 0.0,
            temp_lim: 0.0,
            steps_per_rad: 0.0,
            step_sin: 0.0,
            step_cos: 0.0,
            norms: Vec::new(),
        }
    }

    fn add_paths(&mut self, paths: &Paths64, jt: JoinType, et: EndType) {
        if paths.is_empty() {
            return;
        }
        self.groups.push(PathGroup {
            paths_in: paths.clone(),
            join_type: jt,
            end_type: et,
            path: Vec::new(),
            paths_out: Vec::new(),
            is_reversed: false,
        });
    }

    fn build_normals(&mut self, path: &Path64) {
        self.norms.clear();
        self.norms.reserve(path.len());
        if path.is_empty() {
            return;
        }
        for i in 0..path.len() - 1 {
            self.norms.push(get_unit_normal(&path[i], &path[i + 1]));
        }
        self.norms
            .push(get_unit_normal(&path[path.len() - 1], &path[0]));
    }

    fn do_square(&mut self, gi: usize, path: &Path64, j: usize, k: usize) {
        let vec = if j == k {
            PtD::new(self.norms[0].y, -self.norms[0].x)
        } else {
            get_avg_unit_vector(
                PtD::new(-self.norms[k].y, self.norms[k].x),
                PtD::new(self.norms[j].y, -self.norms[j].x),
            )
        };

        // now offset the original vertex delta units along unit vector
        let mut pt_q = PtD::new(path[j].x as f64, path[j].y as f64);
        pt_q = translate_point(pt_q, self.abs_delta * vec.x, self.abs_delta * vec.y);

        // get perpendicular vertices
        let pt1 = translate_point(pt_q, self.group_delta * vec.y, self.group_delta * -vec.x);
        let pt2 = translate_point(pt_q, self.group_delta * -vec.y, self.group_delta * vec.x);

        // get 2 vertices along one edge offset
        let pt3 = get_perpendic_d(&path[k], &self.norms[k], self.group_delta);
        if j == k {
            let pt4 = PtD::new(
                pt3.x + vec.x * self.group_delta,
                pt3.y + vec.y * self.group_delta,
            );
            let pt = intersect_point(pt1, pt2, pt3, pt4);
            // get the second intersect point through reflection
            let r = reflect_point(pt, pt_q);
            self.groups[gi].path.push(to_point64(r.x, r.y));
            self.groups[gi].path.push(to_point64(pt.x, pt.y));
        } else {
            let pt4 = get_perpendic_d(&path[j], &self.norms[k], self.group_delta);
            let pt = intersect_point(pt1, pt2, pt3, pt4);
            self.groups[gi].path.push(to_point64(pt.x, pt.y));
            // get the second intersect point through reflection
            let r = reflect_point(pt, pt_q);
            self.groups[gi].path.push(to_point64(r.x, r.y));
        }
    }

    fn do_miter(&mut self, gi: usize, path: &Path64, j: usize, k: usize, cos_a: f64) {
        let q = self.group_delta / (cos_a + 1.0);
        let x = path[j].x as f64 + (self.norms[k].x + self.norms[j].x) * q;
        let y = path[j].y as f64 + (self.norms[k].y + self.norms[j].y) * q;
        self.groups[gi].path.push(to_point64(x, y));
    }

    fn do_round(&mut self, gi: usize, path: &Path64, j: usize, k: usize, angle: f64) {
        let pt = path[j];
        let mut offset_vec = PtD::new(
            self.norms[k].x * self.group_delta,
            self.norms[k].y * self.group_delta,
        );
        if j == k {
            offset_vec.x = -offset_vec.x;
            offset_vec.y = -offset_vec.y;
        }
        self.groups[gi]
            .path
            .push(to_point64(pt.x as f64 + offset_vec.x, pt.y as f64 + offset_vec.y));
        let steps = (self.steps_per_rad * angle.abs()).ceil() as i64;
        for _ in 1..steps {
            // ie 1 less than steps
            offset_vec = PtD::new(
                offset_vec.x * self.step_cos - self.step_sin * offset_vec.y,
                offset_vec.x * self.step_sin + offset_vec.y * self.step_cos,
            );
            self.groups[gi]
                .path
                .push(to_point64(pt.x as f64 + offset_vec.x, pt.y as f64 + offset_vec.y));
        }
        let last = get_perpendic(&pt, &self.norms[j], self.group_delta);
        self.groups[gi].path.push(last);
    }

    fn do_bevel(&mut self, gi: usize, path: &Path64, j: usize, k: usize) {
        let (pt1, pt2);
        if j == k {
            let abs_delta = self.group_delta.abs();
            pt1 = PtD::new(
                path[j].x as f64 - abs_delta * self.norms[j].x,
                path[j].y as f64 - abs_delta * self.norms[j].y,
            );
            pt2 = PtD::new(
                path[j].x as f64 + abs_delta * self.norms[j].x,
                path[j].y as f64 + abs_delta * self.norms[j].y,
            );
        } else {
            pt1 = PtD::new(
                path[j].x as f64 + self.group_delta * self.norms[k].x,
                path[j].y as f64 + self.group_delta * self.norms[k].y,
            );
            pt2 = PtD::new(
                path[j].x as f64 + self.group_delta * self.norms[j].x,
                path[j].y as f64 + self.group_delta * self.norms[j].y,
            );
        }
        self.groups[gi].path.push(to_point64(pt1.x, pt1.y));
        self.groups[gi].path.push(to_point64(pt2.x, pt2.y));
    }

    fn offset_point(&mut self, gi: usize, path: &Path64, j: usize, k: &mut usize) {
        // Let A = change in angle where edges join
        // A == 0: ie no change in angle (flat join)
        // A == PI: eg 'spike'
        // sin(A) < 0: right turning
        // cos(A) < 0: change in angle is more than 90 degree
        if pt_eq(&path[j], &path[*k]) {
            *k = j;
            return;
        }

        let mut sin_a = cross_product(self.norms[j], self.norms[*k]);
        let cos_a = dot_product(self.norms[j], self.norms[*k]);
        if sin_a > 1.0 {
            sin_a = 1.0;
        } else if sin_a < -1.0 {
            sin_a = -1.0;
        }

        if cos_a > -0.999 && sin_a * self.group_delta < 0.0 {
            // test for concavity first (#593)
            // is concave
            let p1 = get_perpendic(&path[j], &self.norms[*k], self.group_delta);
            // this extra point is the only (simple) way to ensure that
            // path reversals are fully cleaned with the trailing clipper
            let p2 = path[j]; // (#405)
            let p3 = get_perpendic(&path[j], &self.norms[j], self.group_delta);
            self.groups[gi].path.push(p1);
            self.groups[gi].path.push(p2);
            self.groups[gi].path.push(p3);
        } else if cos_a > 0.999 && self.miter_limit > 1.0 {
            // almost straight - less than 2.5 degree (#424)
            self.do_miter(gi, path, j, *k, cos_a);
        } else if self.groups[gi].join_type == JoinType::Miter {
            // miter unless the angle is so acute it exceeds the miter limit
            if cos_a > self.temp_lim - 1.0 {
                self.do_miter(gi, path, j, *k, cos_a);
            } else {
                self.do_square(gi, path, j, *k);
            }
        } else if self.groups[gi].join_type == JoinType::Round {
            self.do_round(gi, path, j, *k, sin_a.atan2(cos_a));
        } else if self.groups[gi].join_type == JoinType::Bevel {
            self.do_bevel(gi, path, j, *k);
        } else {
            self.do_square(gi, path, j, *k);
        }

        *k = j;
    }

    fn offset_polygon(&mut self, gi: usize, path: &Path64) {
        self.groups[gi].path.clear();
        let mut k = path.len() - 1;
        for i in 0..path.len() {
            self.offset_point(gi, path, i, &mut k);
        }
        let out = std::mem::take(&mut self.groups[gi].path);
        self.groups[gi].paths_out.push(out);
    }

    fn offset_open_joined(&mut self, gi: usize, path: &Path64) {
        self.offset_polygon(gi, path);
        let mut reverse_path = path.clone();
        reverse_path.reverse();

        // rebuild normals
        self.norms.reverse();
        let n0 = self.norms[0];
        self.norms.push(n0);
        self.norms.remove(0);

        self.offset_polygon(gi, &reverse_path);
    }

    fn offset_open_path(&mut self, gi: usize, path: &Path64) {
        let et = self.groups[gi].end_type;

        // do the line start cap
        match et {
            EndType::Butt => {
                let p1 = to_point64(
                    path[0].x as f64 - self.norms[0].x * self.group_delta,
                    path[0].y as f64 - self.norms[0].y * self.group_delta,
                );
                let p2 = get_perpendic(&path[0], &self.norms[0], self.group_delta);
                self.groups[gi].path.push(p1);
                self.groups[gi].path.push(p2);
            }
            EndType::Round => self.do_round(gi, path, 0, 0, PI),
            _ => self.do_square(gi, path, 0, 0),
        }

        let high_i = path.len() - 1;

        // offset the left side going forward
        let mut k = 0usize;
        for i in 1..high_i {
            self.offset_point(gi, path, i, &mut k);
        }

        // reverse normals for the return trip
        for i in (1..=high_i).rev() {
            self.norms[i] = PtD::new(-self.norms[i - 1].x, -self.norms[i - 1].y);
        }
        self.norms[0] = self.norms[high_i];

        // do the line end cap
        match et {
            EndType::Butt => {
                let p1 = to_point64(
                    path[high_i].x as f64 - self.norms[high_i].x * self.group_delta,
                    path[high_i].y as f64 - self.norms[high_i].y * self.group_delta,
                );
                let p2 = get_perpendic(&path[high_i], &self.norms[high_i], self.group_delta);
                self.groups[gi].path.push(p1);
                self.groups[gi].path.push(p2);
            }
            EndType::Round => self.do_round(gi, path, high_i, high_i, PI),
            _ => self.do_square(gi, path, high_i, high_i),
        }

        // offset the left side going back
        let mut k = high_i;
        for i in (1..=high_i).rev() {
            self.offset_point(gi, path, i, &mut k);
        }

        let out = std::mem::take(&mut self.groups[gi].path);
        self.groups[gi].paths_out.push(out);
    }

    fn do_group_offset(&mut self, gi: usize, delta: f64) {
        let et = self.groups[gi].end_type;
        let mut delta = delta;
        if et != EndType::Polygon {
            delta = delta.abs() * 0.5;
        }
        if delta == 0.0 {
            return;
        }
        self.group_delta = delta;
        self.abs_delta = self.group_delta.abs();

        // calculate a sensible number of steps (for 360 degrees for the
        // following offset arc)
        let arc_tol = if self.arc_tolerance > FLOATING_POINT_TOLERANCE {
            self.arc_tolerance
        } else {
            (2.0 + self.abs_delta).log10() * DEFAULT_ARC_TOLERANCE // empirically derived
        };

        // calculate steps per 180 degrees (see offset_trigometry2.svg)
        let mut steps_per_360 = PI / (1.0 - arc_tol / self.abs_delta).acos();
        if steps_per_360 > self.abs_delta * PI {
            steps_per_360 = self.abs_delta * PI; // ensures excessive precision almost certainly
        }
        if self.groups[gi].join_type == JoinType::Round {
            self.step_sin = (2.0 * PI / steps_per_360).sin();
            self.step_cos = (2.0 * PI / steps_per_360).cos();
            if self.group_delta < 0.0 {
                self.step_sin = -self.step_sin;
            }
        }
        self.steps_per_rad = steps_per_360 / (2.0 * PI);

        let is_closed = is_closed_path(et);
        // the lowermost polygon must be an outer polygon. So we can use that as
        // the designated orientation for outer polygons (needed for tidy-up
        // clipping)
        let lowest_idx = match get_lowest_poly_idx(&self.groups[gi].paths_in) {
            Some(i) => i,
            None => return,
        };
        let a = area(&self.groups[gi].paths_in[lowest_idx]);
        // if the lowest area polygon is negative then reverse the offset delta
        self.groups[gi].is_reversed = a < 0.0;
        if self.groups[gi].is_reversed {
            self.group_delta = -self.group_delta;
        }

        for pi in 0..self.groups[gi].paths_in.len() {
            let path = strip_duplicates(&self.groups[gi].paths_in[pi], is_closed);
            let cnt = path.len();
            if cnt == 0 || (cnt < 2 && et == EndType::Polygon) {
                continue;
            }

            if cnt == 1 {
                // single vertex so build a circle or square ...
                if self.groups[gi].join_type == JoinType::Round && et == EndType::Round {
                    // treat as a round-capped dot; emulate DoRound with a unit
                    // normal of (1, 0)
                    self.norms.clear();
                    self.norms.push(PtD::new(1.0, 0.0));
                    self.groups[gi].path.clear();
                    self.do_round(gi, &path, 0, 0, 2.0 * PI);
                } else {
                    let d = self.group_delta;
                    let p = path[0];
                    let mut sq: Path64 = Vec::with_capacity(4);
                    sq.push(to_point64(p.x as f64 - d, p.y as f64 - d));
                    sq.push(to_point64(p.x as f64 + d, p.y as f64 - d));
                    sq.push(to_point64(p.x as f64 + d, p.y as f64 + d));
                    sq.push(to_point64(p.x as f64 - d, p.y as f64 + d));
                    self.groups[gi].paths_out.push(sq);
                    continue;
                }
                let out = std::mem::take(&mut self.groups[gi].path);
                self.groups[gi].paths_out.push(out);
            } else {
                self.build_normals(&path);
                match et {
                    EndType::Polygon => self.offset_polygon(gi, &path),
                    EndType::Joined => self.offset_open_joined(gi, &path),
                    _ => self.offset_open_path(gi, &path),
                }
            }
        }
    }

    fn execute(mut self, delta: f64) -> Paths64 {
        let mut solution: Paths64 = Vec::new();
        if self.groups.is_empty() {
            return solution;
        }

        if delta.abs() < FLOATING_POINT_TOLERANCE {
            // if delta is negligible, retain the untouched paths
            for g in &self.groups {
                for p in &g.paths_in {
                    solution.push(p.clone());
                }
            }
            return solution;
        }

        self.temp_lim = if self.miter_limit <= 1.0 {
            2.0
        } else {
            2.0 / (self.miter_limit * self.miter_limit)
        };

        for gi in 0..self.groups.len() {
            self.do_group_offset(gi, delta);
            solution.append(&mut self.groups[gi].paths_out);
        }

        // clean up self-intersections (Clipper64 with FillRule::Positive)
        union(&solution, FillRule::Positive)
    }
}

#[derive(Clone, Copy, Default)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Point64 {
        Point64 { x, y }
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

pub fn union(paths: &Paths64, _fr: FillRule) -> Paths64 {
    paths.clone()
}

pub fn area(path: &Path64) -> f64 {
    let cnt = path.len();
    if cnt < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    let mut prev = &path[cnt - 1];
    for p in path.iter() {
        a += (prev.y + p.y) as f64 * (prev.x - p.x) as f64;
        prev = p;
    }
    a * 0.5
}

