// Clipper2's CrossProduct(pt1, pt2) for PointD uses the component order
// (pt1.y * pt2.x - pt1.x * pt2.y), so that in OffsetPoint
// sin_a = CrossProduct(norms[j], norms[k]) yields +sin(A) where A is the
// signed change in angle from the incoming edge (k) to the outgoing edge (j).
#[inline]
fn cross_product(a: PtD, b: PtD) -> f64 {
    a.y * b.x - a.x * b.y
}
